if(!window.__apGeoPlannerBound){
  window.__apGeoPlannerBound=true;
  document.addEventListener('click',function(e){
    var add=e.target.closest('[data-add-geo-feature]');
    if(add){
      var root=add.closest('[data-geojson-planner]');
      var layer=root.querySelector('[data-geo-layer]');
      var svg=root.querySelector('[data-geo-svg]');
      var name=root.querySelector('[data-geo-name]').value || 'Location';
      var type=root.querySelector('[data-geo-type]').value || 'Special';
      var count=layer.querySelectorAll('.geo-cell').length;
      var cx=160+((count*175)%690), cy=130+((count*90)%240), rx=95, ry=58;
      var pts=[];
      for(var i=0;i<10;i++){var a=(Math.PI*2*i/10)-Math.PI/2; pts.push([Math.round(cx+Math.cos(a)*rx),Math.round(cy+Math.sin(a)*ry)]);}
      var color={Government:'#176b3a',Medical:'#ca3030',Worship:'#4b197d',Forest:'#247b2e',Market:'#d79a2b',Dock:'#2e9ccc',Residential:'#7c8aa6',Special:'#c46cff'}[type] || '#c46cff';
      var ns='http://www.w3.org/2000/svg';
      var g=document.createElementNS(ns,'g'); g.classList.add('geo-cell'); g.dataset.name=name; g.dataset.type=type; g.dataset.color=color;
      var poly=document.createElementNS(ns,'polygon'); poly.setAttribute('points',pts.map(function(p){return p.join(',')}).join(' ')); poly.setAttribute('fill',color); poly.setAttribute('fill-opacity','.38'); poly.setAttribute('stroke',color); poly.setAttribute('stroke-width','5'); g.appendChild(poly);
      pts.forEach(function(p){var c=document.createElementNS(ns,'circle'); c.setAttribute('cx',p[0]); c.setAttribute('cy',p[1]); c.setAttribute('r','10'); c.setAttribute('class','geo-anchor'); g.appendChild(c);});
      var pin=document.createElementNS(ns,'path'); pin.setAttribute('class','geo-pin'); pin.setAttribute('d','M'+cx+' '+(cy-38)+' C'+(cx-26)+' '+(cy-38)+' '+(cx-36)+' '+(cy-8)+' '+cx+' '+(cy+44)+' C'+(cx+36)+' '+(cy-8)+' '+(cx+26)+' '+(cy-38)+' '+cx+' '+(cy-38)+' Z'); pin.style.color=color; g.appendChild(pin);
      layer.appendChild(g);
      root.querySelector('[data-geojson-output]').value=JSON.stringify(buildGeoJson(root),null,2);
    }
    var exp=e.target.closest('[data-export-geojson-plan]');
    if(exp){var r=exp.closest('[data-geojson-planner]'); r.querySelector('[data-geojson-output]').value=JSON.stringify(buildGeoJson(r),null,2);}
    function buildGeoJson(root){
      return {type:'FeatureCollection', features:Array.from(root.querySelectorAll('.geo-cell')).map(function(g,i){
        var pts=Array.from(g.querySelectorAll('.geo-anchor')).map(function(c){return [Number(c.getAttribute('cx')),Number(c.getAttribute('cy'))];});
        return {type:'Feature', id:'location-'+(i+1), properties:{name:g.dataset.name,type:g.dataset.type,overlayLabelRule:'No visible names on map image; details belong in inspector/panel.', anchors:10}, geometry:{type:'Polygon', coordinates:[pts.concat([pts[0]])]}};
      })};
    }
  });
}

