if(!window.__apConvoRandomizerBound){
  window.__apConvoRandomizerBound=true;
  var recent=[];
  document.addEventListener('click',function(e){
    var scan=e.target.closest('[data-convo-scan]');
    var clear=e.target.closest('[data-convo-clear]');
    if(clear){recent=[]; var r=clear.closest('[data-convo-randomizer]'); r.querySelector('[data-convo-output]').textContent='Recent response memory cleared.'; return;}
    if(!scan)return;
    var root=scan.closest('[data-convo-randomizer]');
    var text=(root.querySelector('[data-convo-input]').value||'').toLowerCase();
    var catalog=[]; try{catalog=JSON.parse(root.querySelector('[data-convo-catalog]').value||'[]');}catch(err){root.querySelector('[data-convo-output]').textContent='Catalog JSON error: '+err.message;return;}
    var tokens=text.split(/[^a-z0-9']+/).filter(Boolean);
    var scored=catalog.map(function(entry,idx){
      var keys=[].concat(entry.keywords||[],entry.triggers||[],entry.topics||[],entry.moods||[],entry.needs||[],entry.tasks||[],entry.asks||[],entry.questions||[],entry.intents||[]);
      var score=keys.reduce(function(n,k){return n+(text.includes(String(k).toLowerCase())?3:0);},0)+tokens.reduce(function(n,t){return n+(keys.join(' ').toLowerCase().includes(t)?1:0);},0);
      return {entry:entry,score:score,idx:idx};
    }).sort(function(a,b){return b.score-a.score;});
    var best=scored[0] && scored[0].score>0 ? scored[0].entry : {responses:['I found no strong match yet. Add keywords/responses to the catalog, then scan again.']};
    var responses=[].concat(best.responses||best.answers||best.replies||best.messages||best.fallback||[]);
    if(!responses.length) responses=['Matched entry, but it has no response text yet.'];
    var options=responses.filter(function(r){return recent.indexOf(r)<0;}); if(!options.length) options=responses;
    var reply=options[Math.floor(Math.random()*options.length)]; recent.push(reply); recent=recent.slice(-12);
    var packet={ok:true,reply:reply,score:scored[0]?scored[0].score:0,signals:{tokens:tokens.slice(0,20)},topCandidates:scored.slice(0,5).map(function(s){return {score:s.score,index:s.idx,title:s.entry.title||s.entry.id||('entry '+s.idx)}})};
    root.querySelector('[data-convo-output]').textContent=JSON.stringify(packet,null,2);
  });
}

